import React, { useState, useEffect } from "react";
import Navbar from "../Components/Navbar";
import Footer from "../Components/Footer";
import "../styles/AdminPages.css";
import API_BASE_URL from "../config";

const MyFlaggedListings = () => {
  const [flagged, setFlagged] = useState([]);
  const userId = sessionStorage.getItem("userId");

  useEffect(() => {
    if (!userId) return;

    fetch(`${API_BASE_URL}/api/listings/flagged/${userId}`)
      .then((res) => res.json())
      .then((data) => setFlagged(data))
      .catch((err) => console.error("Error loading flagged listings:", err));
  }, [userId]);

  return (
    <div>
      <Navbar />
      <main className="favorites-wrapper">
        <h2>My Flagged Listings</h2>
        <div className="favorites-grid">
          {Array.isArray(flagged) && flagged.length > 0 ? (
            flagged.map((item) => (
              <div className="favorite-card" key={item.id}>
                <img
                  src={item.image || "https://via.placeholder.com/300x200"}
                  alt={item.title}
                />
                <h4>{item.title}</h4>
                <p><strong>Reason:</strong> {item.reason || "No reason provided"}</p>
              </div>
            ))
          ) : (
            <p>You haven’t flagged any listings yet.</p>
          )}
        </div>
      </main>
      <Footer />
    </div>
  );
};

export default MyFlaggedListings;
